    let mut app = App::new();
    for c in ['\u{0}', '\u{7f}', 'a', 'z', 'A', '1', '/'] {
        app.on_char_key(c);
    }
    let control = ['\u{0}', '\u{1}'].iter().all(|c| c.is_control());
    assert!(control);
    assert!(!'a'.is_control());
    println!("ok");
}
