use std::cmp::max;

fn draw_basic_cpu_width(width: u16) -> (usize, usize) {
	let draw_loc_width = width;
	let REQUIRED_COLUMNS: usize = 4;
	let margin_space = 2;
	let remaining_width = max(
		0,
		draw_loc_width as i64 - ((9 + margin_space) * REQUIRED_COLUMNS) as i64,
	) as usize;
	let bar_length = remaining_width / REQUIRED_COLUMNS;
	(remaining_width, bar_length)
}

fn draw_basic_memory_width(width: u16) -> usize {
	max(0, width as i64 - 11) as usize
}

fn main() {
	// Check narrow widths produce non-negative values and valid bar lengths.
	for w in &[30u16, 44, 45, 50, 60, 80, 120, 200] {
		let (rw, bl) = draw_basic_cpu_width(*w);
		// Each column: 3 (name) + 1 ('[') + bar_length + 5 (" %]") = 9 + bar_length
		// Total used must not exceed the width for 4 columns.
		let column_used = 9 + bl + 1 + 4 + 1 + 1; // 3 name + '[' + bars + ' ]%' ... simplified check below
		assert!(
			bl as u16 * 4 <= *w,
			"width {}: bar_length {} x4 exceeds width",
			w,
			bl
		);
		assert_eq!(rw % REQUIRED_COLUMNS_4(), 0, "remaining not divisible by 4");
		println!("width={}: remaining_width={}, bar_length={}", w, rw, bl);
	}
	let mem_len = draw_basic_memory_width(30);
	assert!(mem_len < 30);
	println!("mem bar_length at width 30 = {} (>= 0, < width)", mem_len);
	println!("OK");
}

fn REQUIRED_COLUMNS_4() -> usize {
	4
}

use std::cmp::max;

fn draw_basic_cpu_width(width: u16) -> (usize, usize) {
	let draw_loc_width = width;
	const REQUIRED_COLUMNS: usize = 4;
	let margin_space = 2;
	let remaining_width = max(
		0,
		draw_loc_width as i64 - ((9 + margin_space) * REQUIRED_COLUMNS) as i64,
	) as usize;
	let bar_length = remaining_width / REQUIRED_COLUMNS;
	(remaining_width, bar_length)
}

fn draw_basic_memory_width(width: u16) -> usize {
	max(0, width as i64 - 11) as usize
}

fn main() {
	// Narrow widths must never produce a negative remaining width (max(0,...) wrap).
	for w in &[30u16, 44, 45, 50, 60, 80, 120, 200] {
		let (rw, bl) = draw_basic_cpu_width(*w);
		// bar_length is the number of bar chars per column; 4 columns must fit.
		assert!(bl as u16 * 4 <= *w, "width {}: bars x 4 exceeds width", w);
		assert!(rw + 44 >= *w as usize, "max(0,..) wrap broken at width {}", w);
		println!("cpu width={}: remaining_width={}, bar_length={}", w, rw, bl);
	}
	let mem_len = draw_basic_memory_width(30);
	assert!(mem_len < 30);
	println!("mem bar_length at width 30 = {} (>= 0, < width)", mem_len);
	println!("OK");
}

