use tui::layout::{Constraint, Direction, Layout, Rect};

fn help_dialog(current_height: u16, help_text_height: u16, width: u16, current_width: u16) -> (Rect, Rect) {
	let help_text_height = std::cmp::min(help_text_height, current_height);

	let vertical = Layout::default()
		.direction(Direction::Vertical)
		.margin(0)
		.constraints(
			[
				Constraint::Length((current_height - help_text_height) / 2),
				Constraint::Length(help_text_height),
				Constraint::Length(
					current_height - help_text_height - (current_height - help_text_height) / 2,
				),
			]
			.as_ref(),
		)
		.split(Rect::new(0, 0, width, current_height));

	let horizontal = Layout::default()
		.direction(Direction::Horizontal)
		.margin(0)
		.constraints(
			if current_width < 100 {
				[Constraint::Length(0), Constraint::Length(current_width), Constraint::Length(0)].as_ref()
			} else {
				[
					Constraint::Percentage(20),
					Constraint::Percentage(60),
					Constraint::Percentage(20),
				]
				.as_ref()
			},
		)
		.split(vertical[1]);

	(vertical[1], horizontal[1])
}

fn dd_dialog(current_height: u16, width: u16) -> Rect {
	let dd_dialog_height = std::cmp::min(7, current_height);
	let vertical = Layout::default()
		.direction(Direction::Vertical)
		.margin(0)
		.constraints(
			[
				Constraint::Length((current_height - dd_dialog_height) / 2),
				Constraint::Length(dd_dialog_height),
				Constraint::Length(
					current_height - dd_dialog_height - (current_height - dd_dialog_height) / 2,
				),
			]
			.as_ref(),
		)
		.split(Rect::new(0, 0, width, current_height));
	vertical[1]
}

// GENERAL_HELP_TEXT.len() == 15 -> help_text_height = 15 + 3 = 18
const GENERAL_H: u16 = 18;

fn main() {
	// Tall terminal, wide terminal: content-sized, centered, 60% width
	let (v, h) = help_dialog(40, GENERAL_H, 200, 200);
	println!("wide: vertical[1]={:?} horizontal[1]={:?}", v, h);
	assert_eq!(v.height, GENERAL_H);
	assert_eq!(v.y, (40 - GENERAL_H) / 2);
	assert!(h.x > 0, "60% split should have left margin");
	assert_eq!(h.width, 200 * 60 / 100);

	// Small terminal width (< 100), normal height: full width
	let (v, h) = help_dialog(40, GENERAL_H, 80, 80);
	println!("narrow: vertical[1]={:?} horizontal[1]={:?}", v, h);
	assert_eq!(v.height, GENERAL_H);
	assert_eq!(v.y, (40 - GENERAL_H) / 2);
	assert_eq!(h.width, 80, "should be full width when < 100");
	assert_eq!(h.x, 0);

	// Very small terminal (< help height): clamped, no panic, fills screen
	let (v, h) = help_dialog(15, GENERAL_H, 80, 80);
	println!("tiny-height: vertical[1]={:?} horizontal[1]={:?}", v, h);
	assert!(v.height <= 15);

	// Delete dialog
	let d = dd_dialog(24, 80);
	println!("dd(24): {:?}", d);
	assert_eq!(d.height, 7);
	assert_eq!(d.y, (24 - 7) / 2);

	let d = dd_dialog(5, 80);
	println!("dd(5): {:?}", d);
	assert!(d.height <= 5);

	// Centering is correct (top == bottom margin)
	let d = dd_dialog(23, 80);
	let top = d.y;
	let bottom = 23 - (d.y + d.height);
	println!("dd(23): {:?} top={} bottom={}", d, top, bottom);
	assert!((top as i32 - bottom as i32).abs() <= 1);

	println!("ALL CHECKS PASSED");
}

