use std::cmp::min;

fn help_chunks(c: u16, content: u16) -> (u16, u16, u16, u16, u16, u16) {
    let h = min(content + 3, c);
    let top = (c - h) / 2;
    let mid = h;
    let bot = c - h - (c - h) / 2;
    assert_eq!(c, top + mid + bot, "vertical slices must tile terminal height");
    // centered: top and bottom equal or differ by 1
    assert!((top as i32 - bot as i32).abs() <= 1, "help box must be centered");
    (c, h, top, mid, bot, 0)
}

fn help_horizontal(w: u16) -> (u16, u16) {
    let (left, mid, right) = if w < 100 {
        (0u16, w, 0u16)
    } else {
        let left = w * 20 / 100;
        let mid = w * 60 / 100;
        (left, mid, w - left - mid)
    };
    assert_eq!(w, left + mid + right, "horizontal slices must tile terminal width");
    (w, mid)
}

fn dd_chunks(c: u16) -> (u16, u16, u16, u16) {
    let h = min(7, c);
    let top = (c - h) / 2;
    let bot = c - h - (c - h) / 2;
    assert_eq!(c, top + h + bot, "dd vertical must tile");
    assert!((top as i32 - bot as i32).abs() <= 1, "dd box must be centered");
    (c, h, top, bot)
}

fn main() {
    // GENERAL_HELP_TEXT.len() = 15 -> content 15, box height 18.
    let content_general = 15u16;
    // content+3 is used (as the task requires), though the current code passes the already-+3 value
    // Here we mimic: help_text_height = len + 3 = 18
    for c in 8..=100u16 {
        let (_, h, top, mid, bot, _) = help_chunks(c, content_general);
        assert!(mid >= 1 && mid == h);
        assert!(top + mid + bot == c);
    }
    for w in 40..=250u16 {
        let (_, midw) = help_horizontal(w);
        if w < 100 { assert_eq!(midw, w); }
        else { assert!(midw > w / 2 && midw < w); }
    }
    for c in 3..=80u16 {
        let (_, h, top, bot) = dd_chunks(c);
        assert!(h == min(7, c));
        assert!(top + h + bot == c);
    }
    println!("HELP(80x24): {:?}", help_chunks(24, content_general));
    println!("HELP(narrow 80 wide): {:?}", help_horizontal(80));
    println!("HELP(wide 200 wide): {:?}", help_horizontal(200));
    println!("DD(24): {:?}", dd_chunks(24));
    println!("DD(5): {:?}", dd_chunks(5));
    println!("ALL ARITHMETIC CHECKS PASSED");
}
EOF
