struct App {
    last_key_press: std::time::Instant,
}

impl App {
    fn new() -> Self {
        App { last_key_press: std::time::Instant::now() }
    }

    pub fn on_char_key(&mut self, caught_char: char) {
        if caught_char.is_control() {
            return;
        }
        if !self.is_in_dialog() {
            let _current_key_press_inst = std::time::Instant::now();
            self.last_key_press = self.last_key_press;
        }
    }

    fn is_in_dialog(&self) -> bool {
        false
    }
}

fn main() {
    let mut app = App::new();
    for c in ['\u{0}', '\u{7f}', 'a', 'z', 'A', '1', '/'] {
        app.on_char_key(c);
    }
    let control = ['\u{0}', '\u{1}'].iter().all(|c| c.is_control());
    assert!(control);
    assert!(!'a'.is_control());
    println!("ok");
}
